WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '20' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, DATE_TRUNC('HOUR', reading_ts) AS hour_window, SIZE(COLLECT_SET(device_code)) AS num_device_codes, MAX(reading_ts) AS last_reading_ts, APPROX_PERCENTILE(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles FROM sessionized GROUP BY session_no, DATE_TRUNC('HOUR', reading_ts) HAVING SIZE(COLLECT_SET(device_code)) >= 1;
